try {
    const response = await fetch('http://localhost:5000/api/vets');
    const result = await response.json();

    if (response.ok && result.success && Array.isArray(result.data)) {
        allVetsFromApi = result.data;
        if (badge) {
            badge.className = 'bg-emerald-100 text-emerald-800 text-xs px-2.5 py-1 rounded-full font-bold border border-emerald-300 flex items-center gap-1';
            badge.innerHTML = `<span class="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span> Live API (${result.data.length} Doctors)`;
        }
        renderVetsGrid(allVetsFromApi);
    } else {
        console.warn('API returned fallback mode:', result);
        throw new Error('API format mismatch or fallback');
    }
} catch (error) {
    console.error('API connection offline:', error);
    if (badge) {
        badge.className = 'bg-amber-100 text-amber-800 text-xs px-2.5 py-1 rounded-full font-bold border border-amber-300 flex items-center gap-1';
        badge.innerHTML = `<span class="w-2 h-2 rounded-full bg-amber-500"></span> Local Offline Mode`;
    }
    if (container) {
        container.innerHTML = `
            <div class="col-span-full bg-surface-container-lowest border border-error/50 p-8 rounded-2xl text-center">
                <span class="material-symbols-outlined text-4xl text-error mb-2">wifi_off</span>
                <h4 class="font-headline-sm font-bold text-on-surface">Failed to load Veterinarians</h4>
                <p class="text-xs text-on-surface-variant mt-1">Could not connect to the API server. Please ensure the backend is running at http://localhost:5000.</p>
            </div>
        `;
    }
}

