// Fetch Live Recommended Veterinarians from API
async function fetchRecommendedVets() {
    const recContainer = document.getElementById('recommendedVetsContainer');
    if (!recContainer) return;

    try {
        const res = await fetch('http://localhost:5000/api/vets');
        const json = await res.json();

        if (res.ok && json.success && Array.isArray(json.data)) {
            if (json.data.length === 0) {
                recContainer.innerHTML = `
                    <div class="col-span-full py-8 flex flex-col items-center justify-center text-on-surface-variant border border-outline-variant/50 rounded-xl bg-surface-container-lowest">
                        <span class="material-symbols-outlined text-4xl mb-2">search_off</span>
                        <span class="font-label-md text-sm font-semibold">No recommended doctors at the moment</span>
                    </div>
                `;
                return;
            }

            recContainer.innerHTML = json.data.slice(0, 4).map(v => {
                const vci = v.vciNumber || v._id || v.id || '';
                const photo = v.photoUrl || 'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=400&auto=format&fit=crop';
                const spec = Array.isArray(v.specialization) && v.specialization.length > 0 ? v.specialization[0] : 'General Practice';
                const qual = v.qualification || 'B.V.Sc & A.H.';
                const exp = v.experienceYears || 0;
                const clinic = v.clinicName || 'Independent Practice';
                const phone = v.phone || v.clinicPhone || 'Not provided';
                const email = v.email || 'Not provided';
                const availStatus = (v.availability && v.availability.status) ? v.availability.status : 'Available';
                const availabilityBadge = availStatus.toLowerCase() === 'available' 
                    ? `<span class="text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded text-[9px] font-bold border border-emerald-200">${availStatus}</span>` 
                    : `<span class="text-amber-700 bg-amber-50 px-2 py-0.5 rounded text-[9px] font-bold border border-amber-200">${availStatus}</span>`;

                return `
                    <div class="bg-surface-container-lowest border border-outline-variant rounded-xl p-md flex flex-col gap-sm hover:shadow-md transition-shadow ambient-shadow">
                        <div class="flex items-center gap-md">
                            <img alt="${v.name}" class="w-14 h-14 rounded-full object-cover border border-outline-variant shrink-0" src="${photo}"/>
                            <div class="min-w-0 flex-1">
                                <h4 class="font-headline-sm text-sm font-bold text-on-surface truncate flex justify-between items-center">
                                    ${v.name}
                                    ${availabilityBadge}
                                </h4>
                                <p class="text-primary text-[11px] font-semibold truncate">${spec}</p>
                                <div class="flex items-center gap-1 text-[11px] text-on-surface-variant mt-0.5">
                                    <span class="material-symbols-outlined text-[12px]">school</span> ${qual} • ${exp} Yrs Exp.
                                </div>
                            </div>
                        </div>

                        <div class="flex flex-col gap-1 text-[11px] text-on-surface-variant bg-surface-container-low p-2 rounded-lg border border-outline-variant/30 mt-1">
                            <div class="flex items-center gap-2 truncate">
                                <span class="material-symbols-outlined text-[14px] shrink-0 text-outline">local_hospital</span>
                                <span class="truncate" title="${clinic}">${clinic}</span>
                            </div>
                            <div class="flex items-center gap-2 truncate">
                                <span class="material-symbols-outlined text-[14px] shrink-0 text-outline">location_on</span>
                                <span class="truncate" title="${v.city || 'Location N/A'}">${v.city || 'Location N/A'}</span>
                            </div>
                            <div class="flex items-center gap-2 truncate">
                                <span class="material-symbols-outlined text-[14px] shrink-0 text-outline">phone</span>
                                <span class="truncate">${phone}</span>
                            </div>
                            <div class="flex items-center gap-2 truncate">
                                <span class="material-symbols-outlined text-[14px] shrink-0 text-outline">email</span>
                                <span class="truncate" title="${email}">${email}</span>
                            </div>
                        </div>

                        <div class="flex justify-between items-center mt-auto pt-2">
                            <div class="flex items-center gap-1 text-xs text-amber-600 font-bold">
                                <span class="material-symbols-outlined text-[14px] text-amber-500 filled-icon">star</span>
                                <span>4.9</span>
                            </div>
                            <a href="vet-profile.html?id=${vci}" class="bg-secondary-container text-on-secondary-container font-label-md text-xs py-1.5 px-3 rounded-lg hover:bg-secondary hover:text-white transition-colors text-center font-bold">
                                Book (₹${v.consultationFee || 499})
                            </a>
                        </div>
                    </div>
                `;
            }).join('');
        } else {
            throw new Error('API format mismatch or fallback');
        }
    } catch(e) {
        console.error('API connection offline:', e);
        recContainer.innerHTML = `
            <div class="col-span-full py-8 flex flex-col items-center justify-center text-error border border-error/30 rounded-xl bg-error-container/20">
                <span class="material-symbols-outlined text-4xl mb-2">wifi_off</span>
                <span class="font-label-md text-sm font-semibold text-center px-4">Failed to connect to the backend server to load veterinarians.</span>
            </div>
        `;
    }
}

