// Fetch Live Recommended Veterinarians from API
async function fetchRecommendedVets() {
    const recContainer = document.getElementById('recommendedVetsContainer');
    if (!recContainer) return;

    try {
        const res = await fetch('http://localhost:5000/api/vets');
        const json = await res.json();
        if (res.ok && json.success && Array.isArray(json.data) && json.data.length > 0) {
            recContainer.innerHTML = json.data.slice(0, 4).map(v => {
                const vci = v.vciNumber || '';
                const photo = v.photoUrl || 'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=400&auto=format&fit=crop';
                const spec = Array.isArray(v.specialization) ? v.specialization[0] : 'General Practice';
                return `
                    <div class="bg-surface-container-lowest border border-outline-variant rounded-xl p-md flex flex-col justify-between gap-sm hover:shadow-md transition-shadow ambient-shadow">
                        <div class="flex items-center gap-md">
                            <img alt="${v.name}" class="w-14 h-14 rounded-full object-cover border border-outline-variant shrink-0" src="${photo}"/>
                            <div class="min-w-0">
                                <h4 class="font-headline-sm text-sm font-bold text-on-surface truncate">${v.name}</h4>
                                <p class="text-on-surface-variant text-xs truncate">${spec}</p>
                                <div class="flex items-center gap-1 text-xs text-amber-600 font-bold mt-0.5">
                                    <span class="material-symbols-outlined text-[14px] text-amber-500 filled-icon">star</span>
                                    <span>4.9</span>
                                    <span class="text-on-surface-variant font-normal text-[10px]">(${v.city || 'Bengaluru'})</span>
                                </div>
                            </div>
                        </div>
                        <a href="vet-profile.html?vci=${vci}" class="mt-sm w-full bg-secondary-container text-on-secondary-container font-label-md text-xs py-2 rounded-lg hover:bg-secondary hover:text-white transition-colors text-center inline-block font-bold">
                            Book Consult (₹${v.consultationFee || 499})
                        </a>
                    </div>
                `;
            }).join('');
        }
    } catch(e) {
        console.warn('Recommended Vets live API offline fallback:', e);
    }
}

