const mongoose = require('mongoose');

const consultationSchema = new mongoose.Schema({
    vetId: { type: String, required: true }, // ID or VCI of the vet
    vetName: { type: String }, // To display easily
    petId: { type: String },
    ownerId: { type: String }, // To filter by owner
    ownerName: { type: String, required: true },
    petName: { type: String, required: true },
    date: { type: String, required: true }, // e.g., "YYYY-MM-DD"
    time: { type: String, required: true }, // e.g., "10:00 AM"
    consultationType: { type: String, default: "Virtual Telehealth Call" },
    fee: { type: Number, default: 499 },
    status: { type: String, enum: ['upcoming', 'completed', 'cancelled'], default: 'upcoming' },
    createdAt: { type: Date, default: Date.now }
});

module.exports = mongoose.model('Consultation', consultationSchema);

const express = require("express");
const router = express.Router();
const Consultation = require("../models/Consultation");
const connectDB = require("../config/db");

// Helper to check DB
function isDbAvailable() {
  return connectDB.isConnected;
}

// GET /api/consultations
// Supports filtering by vetId or ownerId
router.get("/", async function (req, res) {
  try {
    const vetId = req.query.vetId;
    const ownerId = req.query.ownerId;

    if (isDbAvailable() && Consultation) {
      const query = {};
      if (vetId) query.vetId = vetId;
      if (ownerId) query.ownerId = ownerId;

      const dbConsultations = await Consultation.find(query).sort({ createdAt: -1 });
      return res.json({
        success: true,
        count: dbConsultations.length,
        data: dbConsultations
      });
    }

    // In-memory fallback if DB not connected
    return res.json({
      success: true,
      count: 0,
      data: [],
      message: "DB not available, returning empty list."
    });
  } catch(err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

// POST /api/consultations
router.post("/", async function (req, res) {
  try {
    const body = req.body;

    if (isDbAvailable() && Consultation) {
      const newConsultation = await Consultation.create(body);
      return res.status(201).json({ success: true, data: newConsultation });
    }

    // In-memory fallback
    const newConsultation = { _id: "consult_" + Date.now(), ...body, createdAt: new Date() };
    return res.status(201).json({ success: true, data: newConsultation, message: "Created in memory only" });
  } catch (err) {
    return res.status(500).json({ success: false, message: err.message });
  }
});

module.exports = router;

