    async function confirmDoctorBooking(btnElement) {
        try {
            // Extract User Data
            const rawUser = localStorage.getItem('currentUser');
            if (!rawUser) {
                alert("Please login first to book a consultation.");
                window.location.href = 'login.html';
                return;
            }
            const currentUser = JSON.parse(rawUser);

            // Extract URL param for Vet ID
            const params = new URLSearchParams(window.location.search);
            const queryId = params.get('id') || params.get('vci');
            if (!queryId) throw new Error("No vet selected.");

            // Extract Selected Date
            const selectedDateBtn = document.querySelector('.date-btn.bg-primary-container');
            let selectedDate = "Not Selected";
            if (selectedDateBtn) {
                const spans = selectedDateBtn.querySelectorAll('span');
                if (spans.length >= 3) {
                    selectedDate = `${spans[1].textContent} ${spans[2].textContent}`;
                }
            }

            // Extract Selected Time
            const selectedTimeBtn = document.querySelector('.time-btn.border-2.border-primary');
            const selectedTime = selectedTimeBtn ? selectedTimeBtn.textContent : "Not Selected";

            // Extract Consult Type
            const selectedTypeBtn = document.querySelector('.consult-type-btn.border-2.border-primary');
            const selectedType = selectedTypeBtn ? selectedTypeBtn.textContent.replace(/videocam|local_hospital/g, '').trim() : "Virtual Telehealth Call";

            // Extract Pet
            const petDropdown = document.getElementById('selectPetDropdown');
            const selectedPet = petDropdown ? petDropdown.options[petDropdown.selectedIndex].text : 'your pet';

            const docNameElem = document.getElementById('profileDoctorName');
            const docName = docNameElem ? docNameElem.textContent : 'the doctor';

            // Show Loading State on Button
            const originalBtnHtml = btnElement ? btnElement.innerHTML : '';
            if (btnElement) {
                btnElement.innerHTML = `<span class="material-symbols-outlined animate-spin" style="animation: spin 1s linear infinite">sync</span> Processing...`;
                btnElement.disabled = true;
            }

            const payload = {
                vetId: queryId,
                vetName: docName,
                ownerId: currentUser.email || currentUser._id || "guest",
                ownerName: currentUser.name || "Pet Parent",
                petName: selectedPet,
                date: selectedDate,
                time: selectedTime,
                consultationType: selectedType,
                fee: 499,
                status: 'upcoming'
            };

            const res = await fetch('http://localhost:5000/api/consultations', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            const json = await res.json();

            if (res.ok && json.success) {
                alert(`Consultation with ${docName} confirmed for ${selectedPet}!\nDate: ${selectedDate}\nTime: ${selectedTime}`);
                window.location.href = 'appointments.html';
            } else {
                throw new Error(json.message || "Failed to book consultation");
            }
        } catch (err) {
            alert("Error booking consultation: " + err.message);
            if (btnElement) {
                btnElement.innerHTML = `<span class="material-symbols-outlined">event_available</span> Confirm & Pay ₹499`;
                btnElement.disabled = false;
            }
        }
    }
</script>
<script src="portal-nav.js"></script>

