let currentFilter = 'all';

function filterAppointments() {
    const searchInput = document.getElementById('searchAppointmentInput');
    const countText = document.getElementById('appointmentCountText');
    const query = (searchInput ? searchInput.value : '').toLowerCase().trim();
    let visibleCount = 0;

    const tableRows = document.querySelectorAll('.appointment-row');

    tableRows.forEach(row => {
        const status = row.getAttribute('data-status');
        const type = row.getAttribute('data-type');
        const searchText = row.getAttribute('data-search') || '';

        const matchesFilter = (currentFilter === 'all') ||
                              (currentFilter === 'upcoming' && status === 'upcoming') ||
                              (currentFilter === 'completed' && status === 'completed') ||
                              (currentFilter === 'in-person' && type === 'in-person');

        const matchesSearch = !query || searchText.toLowerCase().includes(query);

        if (matchesFilter && matchesSearch) {
            row.classList.remove('hidden');
            visibleCount++;
        } else {
            row.classList.add('hidden');
        }
    });

    if (countText) {
        countText.textContent = `Showing ${visibleCount} of ${tableRows.length} appointments`;
    }
}

async function loadAppointments(user) {
    const tbody = document.getElementById('appointmentsTableBody');
    try {
        const queryParam = (user.role === 'doctor') ? `vetId=${user._id || user.vci}` : `ownerId=${user.email || user._id || 'guest'}`;
        const res = await fetch(`http://localhost:5000/api/consultations?${queryParam}`);
        const json = await res.json();

        if (res.ok && json.success) {
            renderAppointments(json.data);
        } else {
            throw new Error(json.message || "Failed to fetch");
        }
    } catch (err) {
        tbody.innerHTML = `<tr><td colspan="6" class="text-center py-lg text-error"><span class="material-symbols-outlined mb-2 text-4xl">error</span><p>Error loading appointments: ${err.message}</p></td></tr>`;
    }
}

function renderAppointments(appointments) {
    const tbody = document.getElementById('appointmentsTableBody');
    if (!appointments || appointments.length === 0) {
        tbody.innerHTML = `<tr><td colspan="6" class="text-center py-lg text-on-surface-variant"><span class="material-symbols-outlined mb-2 text-4xl">event_busy</span><p>No appointments found.</p><a href="find-vets.html" class="text-primary font-bold mt-2 inline-block">Book Now</a></td></tr>`;
        updateMetrics(0, 0, 0, 0);
        filterAppointments();
        return;
    }

    let today = 0, upcoming = 0, completed = 0, cancelled = 0;

    tbody.innerHTML = appointments.map(appt => {
        const isVirtual = appt.consultationType.toLowerCase().includes('virtual');
        const typeIcon = isVirtual ? 'videocam' : 'local_hospital';
        const typeClass = isVirtual ? 'text-primary' : 'text-secondary';

        let statusBadge = '';
        if (appt.status === 'upcoming') {
            upcoming++;
            statusBadge = `<span class="inline-flex items-center px-2.5 py-1 rounded-full bg-blue-50 text-blue-700 font-label-md text-xs border border-blue-200 font-bold"><span class="w-1.5 h-1.5 rounded-full bg-blue-500 mr-2"></span> Confirmed</span>`;
        } else if (appt.status === 'completed') {
            completed++;
            statusBadge = `<span class="inline-flex items-center px-2.5 py-1 rounded-full bg-emerald-50 text-emerald-700 font-label-md text-xs border border-emerald-200 font-bold"><span class="w-1.5 h-1.5 rounded-full bg-emerald-500 mr-2"></span> Completed</span>`;
        } else if (appt.status === 'cancelled') {
            cancelled++;
            statusBadge = `<span class="inline-flex items-center px-2.5 py-1 rounded-full bg-red-50 text-red-700 font-label-md text-xs border border-red-200 font-bold"><span class="w-1.5 h-1.5 rounded-full bg-red-500 mr-2"></span> Cancelled</span>`;
        } else {
            statusBadge = `<span class="inline-flex items-center px-2.5 py-1 rounded-full bg-gray-50 text-gray-700 font-label-md text-xs border border-gray-200 font-bold">${appt.status}</span>`;
        }

        return `
        <tr class="appointment-row hover:bg-surface-container-low transition-colors" data-status="${appt.status}" data-type="${isVirtual ? 'virtual' : 'in-person'}" data-search="${appt.vetName} ${appt.petName} ${appt.consultationType}">
            <td class="py-md px-lg">
                <div class="flex items-center gap-md">
                    <div class="w-11 h-11 rounded-full bg-surface-container flex items-center justify-center shrink-0 border border-outline-variant">
                        <span class="material-symbols-outlined text-on-surface-variant">person</span>
                    </div>
                    <div>
                        <span class="font-body-md text-body-md font-bold text-on-surface block">${appt.vetName || 'Doctor'}</span>
                        <span class="text-xs text-on-surface-variant">General Practice</span>
                    </div>
                </div>
            </td>
            <td class="py-md px-lg">
                <div class="flex items-center gap-sm">
                    <div class="w-9 h-9 rounded-full bg-secondary-container flex items-center justify-center text-on-secondary-container font-bold">
                        <span class="material-symbols-outlined text-[18px]">pets</span>
                    </div>
                    <div>
                        <div class="font-body-sm text-body-sm font-semibold text-on-surface">${appt.petName || 'Patient'}</div>
                        <div class="font-label-md text-[10px] text-on-surface-variant uppercase tracking-wider">Pet</div>
                    </div>
                </div>
            </td>
            <td class="py-md px-lg">
                <div class="font-body-sm text-body-sm text-on-surface font-bold">${appt.date}</div>
                <div class="font-label-md text-xs text-primary font-semibold">${appt.time}</div>
            </td>
            <td class="py-md px-lg">
                <span class="inline-flex items-center gap-1 font-body-sm text-body-sm text-on-surface-variant">
                    <span class="material-symbols-outlined text-[16px] ${typeClass}">${typeIcon}</span> ${appt.consultationType}
                </span>
            </td>
            <td class="py-md px-lg">${statusBadge}</td>
            <td class="py-md px-lg text-right">
                ${appt.status === 'upcoming' && isVirtual ? `<a href="live-chat.html" class="inline-flex items-center gap-1.5 px-3.5 py-1.5 bg-primary text-white rounded-lg font-label-md text-xs font-bold hover:bg-primary-container transition-all shadow-sm"><span class="material-symbols-outlined text-[18px]">videocam</span> Join</a>` : ''}
                ${appt.status === 'upcoming' && !isVirtual ? `<button onclick="openRescheduleModal('${appt.vetName || 'Doctor'}', '${appt.petName || 'Pet'}')" class="p-2 text-on-surface-variant hover:text-primary hover:bg-surface-container rounded-lg transition-colors inline-flex items-center gap-1 font-label-md text-xs font-semibold"><span class="material-symbols-outlined text-[18px]">edit_calendar</span> Reschedule</button>` : ''}
                ${appt.status === 'completed' ? `<a href="prescription.html" class="inline-flex items-center gap-1 px-3 py-1.5 bg-surface-variant text-on-surface-variant rounded-lg font-label-md text-xs font-semibold hover:bg-primary hover:text-white transition-all shadow-sm"><span class="material-symbols-outlined text-[16px]">description</span> Rx</a>` : ''}
            </td>
        </tr>
        `;
    }).join('');

    updateMetrics(today, upcoming, completed, cancelled);
    filterAppointments();
}

function updateMetrics(today, upcoming, completed, cancelled) {
    if(document.getElementById('metricToday')) document.getElementById('metricToday').textContent = today;
    if(document.getElementById('metricUpcoming')) document.getElementById('metricUpcoming').textContent = upcoming;
    if(document.getElementById('metricCompleted')) document.getElementById('metricCompleted').textContent = completed;
    if(document.getElementById('metricCancelled')) document.getElementById('metricCancelled').textContent = cancelled;
}

document.addEventListener('DOMContentLoaded', () => {
    const rawUser = localStorage.getItem('currentUser');
    const token = localStorage.getItem('userToken');
    if (!token || !rawUser) {
        window.location.href = 'login.html';
