async function fetchPets() {
    try {
        const ownerIdParam = currentUserObj._id || currentUserObj.id || currentUserObj.email;
        const res = await fetch(`http://localhost:5000/api/pets?ownerId=${ownerIdParam}`, {
            headers: { 'Authorization': `Bearer ${token}` }
        });
        const json = await res.json();
        if (res.ok && json.data) {
            allPetsData = json.data;
            updateMetrics(allPetsData);
            renderPets(allPetsData);
        }
    } catch (err) {
        console.error('API Error:', err);
        gridContainer.innerHTML = `
            <div class="col-span-full text-center py-xl text-error">
                <span class="material-symbols-outlined text-4xl mb-2">error</span>
                <p class="font-bold">Failed to load pets from backend API (http://localhost:5000)</p>
            </div>
        `;
    }
}

