        const ownerIdParam = currentUserObj._id || currentUserObj.id || currentUserObj.email;
        const res = await fetch(`http://localhost:5000/api/pets?ownerId=${ownerIdParam}`, {
            headers: { 'Authorization': `Bearer ${token}` }
        });
        const json = await res.json();
        if (json.success && json.data) {
            renderPets(json.data);
        }
    } catch (err) {
        console.warn('API fetch error:', err);
        renderPets([]);
    }
}

