    // Fetch Consultations
    async function fetchConsultations() {
        const listContainer = document.getElementById('recentConsultationsList');
        if (!listContainer) return;
        try {
            const ownerIdParam = currentUserObj._id || currentUserObj.id || currentUserObj.email;
            const res = await fetch(`http://localhost:5000/api/consultations?ownerId=${ownerIdParam}`, {
                headers: { 'Authorization': `Bearer ${token}` }
            });
            const json = await res.json();
            if (json.success && json.data) {
                renderConsultations(json.data);
            } else {
                renderConsultations([]);
            }
        } catch(e) {
            console.error('Consultations fetch error:', e);
            listContainer.innerHTML = `<div class="p-4 text-center text-error font-bold">Failed to load consultations</div>`;
        }
    }

    function renderConsultations(consultations) {
        const listContainer = document.getElementById('recentConsultationsList');
        if (!listContainer) return;

        if (consultations.length === 0) {
            listContainer.innerHTML = `<div class="p-4 text-center text-on-surface-variant text-sm font-semibold">No consultations found.</div>`;
            return;
        }

        // Show up to 4 recent
        listContainer.innerHTML = consultations.slice(0, 4).map(c => {
            const statusClass = c.status === 'completed' ? 'bg-secondary-container/40 text-on-secondary-container' : 
                              c.status === 'cancelled' ? 'bg-error-container text-on-error-container' : 
                              'bg-primary-container text-on-primary-container';

            return `
                <div class="flex items-center justify-between p-sm hover:bg-surface-container-low rounded-lg transition-colors border-b border-surface-container-lowest">
                    <div class="flex items-center gap-md">
                        <div class="w-10 h-10 rounded-full bg-surface-container flex items-center justify-center text-primary overflow-hidden shrink-0">
                            <span class="material-symbols-outlined text-[20px]">pets</span>
                        </div>
                        <div class="min-w-0">
                            <p class="font-label-md text-label-md text-on-surface truncate">${c.reasonForVisit || c.consultationType || 'Consultation'}</p>
                            <p class="text-on-surface-variant font-body-sm text-body-sm text-[12px] truncate">${c.petName} • ${c.date}</p>
                        </div>
                    </div>
                    <span class="${statusClass} px-2 py-1 rounded-full text-[10px] font-bold shrink-0 capitalize">${c.status}</span>
                </div>
            `;
        }).join('');

        // Try to find the upcoming one
        const upcoming = consultations.find(c => c.status === 'upcoming');
        if (upcoming) {
            // We can dynamically render the upcoming card if needed.
            // For now, keeping the static structure or update it if possible
        }
    }

    // Initial Fetches
    fetchPets();
    fetchRecommendedVets();
    fetchConsultations();
});

