document.addEventListener('DOMContentLoaded', async () => {
    const urlParams = new URLSearchParams(window.location.search);
    // It could be appointmentId or prescriptionId depending on how it was linked, but for simplicity let's assume it gets passed prescriptionId directly or we fetch all and find by appt
    // Let's assume it gets passed prescriptionId in URL. Wait, appointments.html passes appointmentId.
    // If appointmentId is passed, we fetch /api/prescriptions and filter by appointmentId, or the backend should have a route.
    // But we don't have that route. We can just fetch all and find the one.
    const appointmentId = urlParams.get('appointmentId');
    const prescriptionId = urlParams.get('prescriptionId');

    try {
        let rx = null;
        if (prescriptionId) {
            const res = await fetch(`http://localhost:5000/api/prescriptions/${prescriptionId}`);
            const json = await res.json();
            if (json.success) rx = json.data;
        } else if (appointmentId) {
            // Fetch all prescriptions and find the one with this appointmentId (not efficient, but works for mock)
            // Or we could have an endpoint. Let's do it client side for now.
            const res = await fetch(`http://localhost:5000/api/prescriptions`);
            const json = await res.json();
            if (json.success && json.prescriptions) {
                rx = json.prescriptions.find(p => p.appointmentId === appointmentId);
            }
        }

        if (rx) {
            if (document.getElementById('patientName')) document.getElementById('patientName').textContent = rx.patientName;
            if (document.getElementById('speciesBreed')) document.getElementById('speciesBreed').textContent = rx.speciesBreed;
            if (document.getElementById('ageWeight')) document.getElementById('ageWeight').textContent = rx.ageWeight;
