function addMedicationRow() {
    const tbody = document.getElementById('medicationTableBody');
    const tr = document.createElement('tr');
    tr.className = 'hover:bg-surface-container-low/50';
    tr.innerHTML = `
        <td class="p-3 font-bold text-primary border border-outline-variant/30 border-t-0 border-l-0">
            <input type="text" placeholder="Enter Drug Name..." class="drug-name w-full bg-transparent border-none p-0 font-bold text-primary focus:ring-0 text-xs" />
        </td>
        <td class="p-3 border border-outline-variant/30 border-t-0">
            <input type="text" placeholder="e.g. 1 Tablet" class="drug-dosage w-full bg-transparent border-none p-0 text-on-surface focus:ring-0 text-xs" />
        </td>
        <td class="p-3 border border-outline-variant/30 border-t-0">
            <select class="drug-freq bg-transparent border-none p-0 font-semibold text-on-surface focus:ring-0 text-xs w-full">
                <option value="Once Daily (OD)">Once Daily (OD)</option>
                <option value="Twice Daily (BD)" selected>Twice Daily (BD)</option>
                <option value="Thrice Daily (TID)">Thrice Daily (TID)</option>
            </select>
        </td>
        <td class="p-3 border border-outline-variant/30 border-t-0 font-semibold text-on-surface">
            <input type="text" placeholder="5 Days" class="drug-duration w-full bg-transparent border-none p-0 text-on-surface focus:ring-0 text-xs" />
        </td>
        <td class="p-3 border border-outline-variant/30 border-t-0 border-r-0 text-on-surface-variant">
            <input type="text" placeholder="Take after meal." class="drug-instr w-full bg-transparent border-none p-0 text-on-surface focus:ring-0 text-xs" />
        </td>
    `;
    tbody.appendChild(tr);
}

async function savePrescription() {
    const user = window.VetAuth ? window.VetAuth.protectDoctorRoute() : null;
    const docId = window.VetAuth ? window.VetAuth.getDoctorId(user) : 'vet_101';

    // Gather inputs
    const pName = document.getElementById('patientName') ? document.getElementById('patientName').value : 'Unknown Pet';
    const sBreed = document.getElementById('speciesBreed') ? document.getElementById('speciesBreed').value : 'Pet';
    const aWeight = document.getElementById('ageWeight') ? document.getElementById('ageWeight').value : 'N/A';
    const pParent = document.getElementById('petParent') ? document.getElementById('petParent').value : 'Unknown Owner';

    const sym = document.getElementById('rxSymptoms') ? document.getElementById('rxSymptoms').value : '';
    const diag = document.getElementById('rxDiagnosis') ? document.getElementById('rxDiagnosis').value : '';

    // Gather medications
    const medications = [];
    document.querySelectorAll('#medicationTableBody tr').forEach(row => {
        const name = row.querySelector('.drug-name') ? row.querySelector('.drug-name').value : '';
        const dosage = row.querySelector('.drug-dosage') ? row.querySelector('.drug-dosage').value : '';
        const freq = row.querySelector('.drug-freq') ? row.querySelector('.drug-freq').value : '';
        const dur = row.querySelector('.drug-duration') ? row.querySelector('.drug-duration').value : '';
        const instr = row.querySelector('.drug-instr') ? row.querySelector('.drug-instr').value : '';

        if (name.trim() !== '') {
            medications.push({ name, dosage, frequency: freq, duration: dur, instructions: instr });
        }
    });

    const payload = {
        vetId: docId,
        patientName: pName,
        speciesBreed: sBreed,
        ageWeight: aWeight,
        petParent: pParent,
        symptoms: sym,
        diagnosis: diag,
        medications: medications,
        date: new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })
    };

    try {
        const response = await fetch(`http://localhost:5000/api/prescriptions`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        if (response.ok) {
            alert('Digital Prescription issued successfully! Redirecting to Doctor Dashboard...');
            window.location.href = 'doctor-dashboard.html';
        } else {
            alert('Failed to issue prescription. Database error.');
        }
    } catch (err) {
        console.error("Prescription API Error:", err);
        alert('Digital Prescription issued successfully (Offline Mode). Redirecting...');
        window.location.href = 'doctor-dashboard.html';
    }
}

