// Populate Doctor Name
// If the logged in user is a doctor, we can use VetAuth.
const doctor = window.VetAuth ? window.VetAuth.protectDoctorRoute(false) : null;
if (doctor && rx.vetId === window.VetAuth.getDoctorId(doctor)) {
    window.VetAuth.populateDoctorHeader(doctor);
    const name = doctor.name || 'Dr. Unknown';
    if (document.getElementById('rxDoctorName')) document.getElementById('rxDoctorName').textContent = name;
    if (document.getElementById('docSignatureBoxName')) document.getElementById('docSignatureBoxName').textContent = name;
    if (document.getElementById('rxDoctorQual')) document.getElementById('rxDoctorQual').textContent = doctor.qualification || 'Veterinarian';
    if (document.getElementById('rxDoctorVci')) document.getElementById('rxDoctorVci').textContent = `VCI Reg: ${doctor.vciNumber || 'N/A'}`;
} else if (rx.vetId) {
    // Fetch vet details from API
    try {
        const vetRes = await fetch(`http://localhost:5000/api/vets/${rx.vetId}`);
        const vetJson = await vetRes.json();
        if (vetJson.success && vetJson.data) {
            const vet = vetJson.data;
            const name = vet.name || 'Dr. Unknown';
            if (document.getElementById('rxDoctorName')) document.getElementById('rxDoctorName').textContent = name;
            if (document.getElementById('docSignatureBoxName')) document.getElementById('docSignatureBoxName').textContent = name;
            if (document.getElementById('rxDoctorQual')) document.getElementById('rxDoctorQual').textContent = vet.qualification || 'Veterinarian';
            if (document.getElementById('rxDoctorVci')) document.getElementById('rxDoctorVci').textContent = `VCI Reg: ${vet.vciNumber || 'N/A'}`;
        }
    } catch (e) {
        console.error("Error fetching vet details", e);
    }
}

