async function confirmDoctorBooking() {
    const petDropdown = document.getElementById('selectPetDropdown');
    const selectedPetId = petDropdown ? petDropdown.value : null;

    if (!selectedPetId) {
        alert("Please select a pet for the appointment.");
        return;
    }

    const docNameElem = document.getElementById('profileDoctorName');
    const docName = docNameElem ? docNameElem.textContent : 'the doctor';

    // Find selected date & time
    let dateVal = "Tomorrow";
    const selectedDateBtn = document.querySelector('.date-btn.border-2.border-primary');
    if(selectedDateBtn) dateVal = selectedDateBtn.textContent.replace(/\n/g, ' ').trim().replace(/\s+/g, ' ');

    let timeVal = "10:00 AM";
    const selectedTimeBtn = document.querySelector('.time-btn.border-2.border-primary');
    if(selectedTimeBtn) timeVal = selectedTimeBtn.textContent.trim();

    let typeVal = "Virtual Telehealth";
    const selectedTypeBtn = document.querySelector('.consult-type-btn.border-2.border-primary');
    if(selectedTypeBtn) typeVal = selectedTypeBtn.textContent.replace(/\n/g, ' ').trim().replace(/\s+/g, ' ');

    // Calculate fees
    const feeElem = document.getElementById('profileConsultFee');
    let feeNum = 499;
    if(feeElem) {
        feeNum = parseInt(feeElem.textContent.replace(/\D/g, '')) || 499;
    }

    // Get vet ID from URL
    const params = new URLSearchParams(window.location.search);
    const queryId = params.get('id') || params.get('vci');

    if (!queryId) {
        alert("Could not identify the veterinarian.");
        return;
    }

    const rawUser = localStorage.getItem('currentUser');
    let currentUser = rawUser ? JSON.parse(rawUser) : null;
    if(!currentUser || currentUser.role === 'doctor' || currentUser.role === 'vet') {
        alert("Please log in as a pet owner to book an appointment.");
        window.location.href = 'index.html';
        return;
    }

    // Post to API
    try {
        const response = await fetch('http://localhost:5000/api/appointments', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                vetId: queryId,
                ownerId: currentUser._id || currentUser.id,
                petId: selectedPetId,
                date: dateVal,
                time: timeVal,
                type: typeVal,
                status: 'scheduled',
                fee: feeNum
            })
        });

        const result = await response.json();
        if(result.success) {
            alert(`Appointment with ${docName} confirmed for ${dateVal} at ${timeVal}! Redirecting to Appointments Center...`);
            window.location.href = 'appointments.html';
        } else {
            alert('Failed to book appointment: ' + result.message);
        }
    } catch(e) {
        console.error("Booking failed", e);
        alert("Network error, could not process booking.");
    }
}

