        specialization: ["Dental", "General Practice"],
        clinicName: "Happy Tails Vet",
        city: "Mumbai",
        consultationFee: 450,
        experienceYears: 5
      }
    ]);

    // 5. Create Appointments
    console.log("Seeding Appointments...");
    const appointments = await Appointment.insertMany([
      {
        vetId: vets[0]._id,
        ownerId: users[0]._id,
        petId: pets[0]._id,
