        ],
        notes: "Follow up in 2 weeks if itching persists.",
        status: "issued"
      }
    ]);

    // 8. Create Chat Messages
    console.log("Seeding Chat Messages...");
    await ChatMessage.insertMany([
      {
        consultationId: consultations[1]._id,
        senderId: users[2]._id,
