      phone: "9876543211",
      password: "password123"
    });
  }).then(function(userRes) {
    console.log("User Created");
    const userId = userRes.user ? (userRes.user._id || userRes.user.id) : "user_1";

    console.log("Creating Pet...");
    return postData('/api/pets', {
      ownerId: userId,
      name: "Sheru",
      species: "Dog",
      breed: "Indian Pariah",
      age: 3,
      weight: 15,
      gender: "Male"
    }).then(function(petRes) {
      console.log("Pet Created");
      const petId = petRes.pet ? (petRes.pet._id || petRes.pet.id) : "pet_1";

      console.log("Creating Appointment...");
